// خوارزمية إقليدس مكتوبة يدويا ومقارنة بالمكتبة القياسية.
استورد std.io.println;
استورد std.text.number;
استورد std.math.integer;

عرف إقليدس(أ: غير_موقع, ب: غير_موقع): غير_موقع {
    دع س: متغير غير_موقع = أ;
    دع ص: متغير غير_موقع = ب;
    بينما (ص != 0) {
        دع الباقي: غير_موقع = س % ص;
        س := ص;
        ص := الباقي;
    }
    أرجع س;
}

عرف القلعة(): عدد {
    اطبع_سطر(غير_موقع_إلى_نص(إقليدس(1071, 462)));
    اطبع_سطر(غير_موقع_إلى_نص(القاسم_المشترك_الأكبر(1071, 462)));
    // المضاعف المشترك الأصغر يرجع `اختيار`: قد لا يتسع الناتج في `غير_موقع`.
    طابق المضاعف_المشترك_الأصغر(4, 6) مع
    | اختيار.بعض(القيمة) -> { اطبع_سطر(غير_موقع_إلى_نص(القيمة)); }
    | اختيار.لا_شيء -> { اطبع_سطر("تجاوز"); };
    أرجع 0;
}

