// غربال إراتوستينس: كل الأعداد الأولية الأصغر من 50.
استورد std.io.println;
استورد std.text.number;
استورد std.text.transform;

عرف القلعة(): عدد {
    دع الحد: غير_موقع = 50;
    دع مركب: متغير متجه منطقي = [];
    دع ف: متغير غير_موقع = 0;
    بينما (ف < الحد) { ألحق(مركب, خطأ); ف := ف + 1; }
    دع الأوليات: متغير متجه نص = [];
    دع المرشح: متغير غير_موقع = 2;
    بينما (المرشح < الحد) {
        لو (!مركب[المرشح]) {
            ألحق(الأوليات, غير_موقع_إلى_نص(المرشح));
            دع المضاعف: متغير غير_موقع = المرشح * المرشح;
            بينما (المضاعف < الحد) {
                مركب[المضاعف] := صواب;
                المضاعف := المضاعف + المرشح;
            }
        };
        المرشح := المرشح + 1;
    }
    دع المسافة: نص = " ";
    اطبع_سطر(صل_النصوص(&الأوليات, &المسافة));
    أرجع 0;
}

