    بينما (ف <= 3) {
        دع السطر: متجه غ8 = بايتات_من_نص(عدد_إلى_نص(ف));
        اكتب_مخزنا(&متغير كاتب, &السطر);
        دع سطر_جديد: متجه غ8 = [10];
        اكتب_مخزنا(&متغير كاتب, &سطر_جديد);
