// A generic ADT and generic functions instantiated with several types.
import std.io.println;
import std.text.number;

type Maybe<T> = | Nothing | Just of T;
type Pair<A, B> = { first: A, second: B };

def value_or<T>(value: Maybe<T>, fallback: T): T {
    match value with
    | Maybe.Nothing -> { return fallback; }
    | Maybe.Just(item) -> { return item; };
}

def flip<A, B>(pair: &Pair<A, B>): Pair<B, A> {
    let result_pair: Pair<B, A> = { first: clone(&(*pair).second), second: clone(&(*pair).first) };
    return result_pair;
}

def main(): int {
    let present: Maybe<int> = Maybe.Just(42);
    let missing: Maybe<int> = Maybe.Nothing();
    let word: Maybe<string> = Maybe.Just("generic");
    println(int_to_text(value_or(present, 0)));
    println(int_to_text(value_or(missing, -1)));
    println(value_or(word, "none"));
    let pair: Pair<int, bool> = { first: 7, second: true };
    let swapped: Pair<bool, int> = flip(&pair);
    if (swapped.first) { println(int_to_text(swapped.second)); };
    return 0;
}

files.examples/en/generics/stack.sn:
// A generic stack record backed by a vector.
import std.io.println;
import std.text.number;

type Stack<T> = { items: vector T };

def new_stack<T>(): Stack<T> {
    let empty: vector T = [];
    let stack: Stack<T> = { items: empty };
    return stack;
}

def push<T>(stack: &mutable Stack<T>, item: T): void {
    append((*stack).items, item);
}

def size<T>(stack: &Stack<T>): uint {
    return length((*stack).items) as uint;
}

def top<T>(stack: &Stack<T>): option T {
    let count: uint = size(stack);
    if (count == 0) { return option.none(); };
    return option.some(clone(&(*stack).items[count - 1]));
}

def main(): int {
    let numbers: mutable Stack<int> = new_stack();
    push(&mutable numbers, 10);
    push(&mutable numbers, 20);
    push(&mutable numbers, 30);
    println(uint_to_text(size(&numbers)));
    match top(&numbers) with
    | option.some(value) -> { println(int_to_text(value)); }
    | option.none -> { println("empty"); };
    return 0;
}

