import std.io.println;
import std.text.number;
import std.time.calendar;
import std.time.date;

def main(): int {
    match new_calendar_date(2026, 11, 4) with
    | option.none -> { return 1; }
    | option.some(date) -> {
        match format_iso_date(&date) with
        | option.some(text) -> { println(text); }
        | option.none -> { };
    };
    return 0;
}

files.examples/en/web/http_response.sn:
// Parsing an HTTP/1.1 response from raw bytes, without a network.
import std.io.println;
import std.text.number;
import std.text.from_bytes;
import std.http.client;

def main(): int {
    let raw: vector u8 = bytes_from_text("HTTP/1.1 200 OK\r\nContent-Length: 5\r\nContent-Type: text/plain\r\n\r\nhello");
    match parse_http1_response(&raw, true, 1024) with
    | result.err(_) -> { println("invalid response"); return 1; }
    | result.ok(parsed) -> {
        // Library records have canonical field names only.
        println(uint_to_text(parsed.الاستجابة.الحالة));
        println(from_bytes(&parsed.الاستجابة.الجسم));
    };
    return 0;
}

files.examples/en/web/mime_types.sn:
// Choosing a media type from a file name.
import std.io.println;
import std.mime.mime;

def main(): int {
    let page: string = "index.html";
    let picture: string = "logo.png";
    let unknown: string = "archive.unknownext";
    let page_type: mime_type = mime_type_from_path_or_default(&page);
    let picture_type: mime_type = mime_type_from_path_or_default(&picture);
    let unknown_type: mime_type = mime_type_from_path_or_default(&unknown);
    println(mime_type_text(&page_type));
    println(mime_type_text(&picture_type));
    println(mime_type_text(&unknown_type));
    return 0;
}

files.examples/en/web/uri.sn:
// Parsing a URI, reading its query, and percent-encoding text.
import std.io.println;
import std.uri.uri;

def main(): int {
    let address: string = "https://example.com/search?q=sultan&lang=ar";
    match parse_uri(&address) with
    | result.ok(parsed) -> { println(uri_to_text(&parsed)); }
    | result.err(_) -> { println("invalid uri"); return 1; };
    let query: string = "q=sultan&lang=ar";
    match parse_uri_query(&query) with
    | result.ok(pairs) -> {
        let name: string = "lang";
        match uri_query_first_value(&pairs, &name) with
        | option.some(value) -> { println(value); }
        | option.none -> { };
    }
    | result.err(_) -> { return 2; };
    let phrase: string = "a b&c";
    println(percent_encode(&phrase));
    return 0;
}

files.examples/en/web/versions.sn:
// Semantic versions: parsing and precedence (a pre-release sorts first).
import std.io.println;
import std.version.semver;

def describe(left: string, right: string): void {
    match parse_semver(&left) with
    | result.err(_) -> { println("invalid version"); }
    | result.ok(a) -> {
        match parse_semver(&right) with
        | result.err(_) -> { println("invalid version"); }
        | result.ok(b) -> {
            let order: int = compare_semver(&a, &b);
            if (order < 0) { println("older"); } else { if (order > 0) { println("newer"); } else { println("same"); }; };
        };
    };
}

def main(): int {
    describe("1.2.3", "1.10.0");
    describe("2.0.0", "2.0.0-beta.1");
    describe("1.0.0", "1.0.0");
    return 0;
}
